async function inspectMetacritic() {
  try {
    const res = await fetch('https://www.metacritic.com/game/', {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'en-US,en;q=0.9'
      }
    });
    console.log('Metacritic /game/ status:', res.status);
    const html = await res.text();
    console.log('Response length:', html.length);
    const hasNextData = html.includes('__NEXT_DATA__');
    console.log('Contains __NEXT_DATA__:', hasNextData);
    if (hasNextData) {
      const match = html.match(/<script id="__NEXT_DATA__" type="application\/json">([^<]+)<\/script>/);
      if (match) {
        const nextData = JSON.parse(match[1]);
        console.log('NextData page:', nextData.page);
        console.log('NextData props keys:', Object.keys(nextData.props || {}));
      }
    }
  } catch (e) {
    console.log('Error:', e.message);
  }
}

await inspectMetacritic();

