import puppeteer from 'puppeteer-extra';
import StealthPlugin from 'puppeteer-extra-plugin-stealth';
import { config } from '../src/config.js';

puppeteer.use(StealthPlugin());

async function inspectGame() {
  const browser = await puppeteer.launch({
    headless: config.headless,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36');

  // Let's first inspect https://www.metacritic.com/game/ to get the exact New Releases URLs
  console.log('Fetching https://www.metacritic.com/game/ ...');
  await page.goto('https://www.metacritic.com/game/', { waitUntil: 'domcontentloaded', timeout: 30000 });

  const releaseLinks = await page.evaluate(() => {
    // Look for New Releases section
    const headings = Array.from(document.querySelectorAll('h2, h3'));
    const nrHeading = headings.find(h => h.innerText.toLowerCase().includes('new releases'));
    const parent = nrHeading ? nrHeading.closest('section') || nrHeading.parentElement?.parentElement : document;

    const anchors = Array.from(parent ? parent.querySelectorAll('a[href*="/game/"]') : []);
    const urls = new Set<string>();
    for (const a of anchors) {
      const href = a.getAttribute('href');
      if (href && href.startsWith('/game/') && !href.includes('/all/') && !href.includes('/news/')) {
        urls.add('https://www.metacritic.com' + href);
      }
    }
    return Array.from(urls);
  });

  console.log('Found New Releases URLs count:', releaseLinks.length);
  console.log('Sample URLs:', releaseLinks.slice(0, 5));

  if (releaseLinks.length > 0) {
    const targetUrl = releaseLinks[0];
    console.log('\nInspecting game page:', targetUrl);
    await page.goto(targetUrl, { waitUntil: 'domcontentloaded', timeout: 30000 });

    const gameData = await page.evaluate(() => {
      // Title
      const titleEl = document.querySelector('h1, .c-productHero_title, [data-testid="hero-title"]');
      const title = titleEl ? (titleEl as HTMLElement).innerText.trim() : '';

      // Cover
      const imgEl = document.querySelector('.c-gameDetails_heroImage img, .c-productHero_image img, [data-testid="hero-image"] img, img.c-cmsImage');
      const cover = imgEl ? (imgEl as HTMLImageElement).src : '';

      // Description
      const descEl = document.querySelector('.c-productionDetailsGames_description, [data-testid="description"], .c-gameDetails_description');
      const description = descEl ? (descEl as HTMLElement).innerText.trim() : '';

      // Developer
      const devEl = document.querySelector('.c-gameDetails_Developer, [data-testid="developer"], .c-productionDetailsGames_developer');
      const developer = devEl ? (devEl as HTMLElement).innerText.trim() : '';

      // Video
      const videoEl = document.querySelector('video, iframe[src*="youtube"], iframe[src*="video"], a[href*="video"]');
      let videoUrl = '';
      if (videoEl) {
        if (videoEl.tagName === 'IFRAME') videoUrl = (videoEl as HTMLIFrameElement).src;
        else if (videoEl.tagName === 'VIDEO') videoUrl = (videoEl as HTMLVideoElement).src;
        else if (videoEl.tagName === 'A') videoUrl = (videoEl as HTMLAnchorElement).href;
      }

      // Platforms / Scores
      const metascoreEl = document.querySelector('[data-testid="metascore"], .c-productScoreInfo_scoreNumber');
      const metascore = metascoreEl ? (metascoreEl as HTMLElement).innerText.trim() : '';

      const userscoreEl = document.querySelector('[data-testid="userscore"], .c-siteReviewScore_user');
      const userscore = userscoreEl ? (userscoreEl as HTMLElement).innerText.trim() : '';

      return { title, cover, description, developer, videoUrl, metascore, userscore };
    });

    console.log('Extracted game data:', gameData);
  }

  await browser.close();
}

inspectGame().catch(console.error);

