import puppeteer from 'puppeteer-extra';
import StealthPlugin from 'puppeteer-extra-plugin-stealth';
import { config } from './config.js';

puppeteer.use(StealthPlugin());

async function inspectGameDetail() {
  const browser = await puppeteer.launch({
    headless: config.headless,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36');

  await page.setRequestInterception(true);
  page.on('request', (req) => {
    const resourceType = req.resourceType();
    if (['font', 'media'].includes(resourceType)) {
      req.abort();
    } else {
      req.continue();
    }
  });

  const url = 'https://www.metacritic.com/game/valheim/';
  console.log('Navigating to', url);
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 20000 });

  const data = await page.evaluate(() => {
    // Title
    const title = document.querySelector('h1')?.textContent?.trim() || '';

    // Images
    const imgs = Array.from(document.querySelectorAll('img')).map(i => i.src);
    const coverImage = imgs.find(s => s.includes('images.metacritic.com') || s.includes('fandom.com') || s.includes('game')) || imgs[0] || '';

    // Developer
    const devSpans = Array.from(document.querySelectorAll('span, div, a'));
    const devLabel = devSpans.find(s => s.textContent?.trim() === 'Developer:');
    const developer = devLabel?.parentElement?.querySelector('a, span:last-child')?.textContent?.trim() || '';

    // Description
    const descEl = document.querySelector('.c-productDetails_description, .description, [class*="description"]');
    const description = descEl?.textContent?.trim() || '';

    // Video
    const video = document.querySelector('video, iframe[src*="youtube"], a[href*="video"]');
    let videoUrl = '';
    if (video?.tagName === 'IFRAME') videoUrl = (video as HTMLIFrameElement).src;
    else if (video?.tagName === 'VIDEO') videoUrl = (video as HTMLVideoElement).src;

    // Platforms & Scores
    // Metacritic displays platforms in a switcher or badges
    const platformEls = Array.from(document.querySelectorAll('[class*="platform"], [class*="Platform"], a[href*="/game/"]'));
    const platforms: { name: string; score?: string }[] = [];

    // Let's also check all scores on page
    const scores = Array.from(document.querySelectorAll('[class*="scoreNumber"], [class*="Score"], [data-testid*="score"]')).map(el => ({
      text: el.textContent?.trim(),
      className: el.className
    }));

    // Reviews snippets
    const reviewCards = Array.from(document.querySelectorAll('[class*="ReviewCard"], [class*="review_quote"], [class*="c-siteReview"]')).map(el => el.textContent?.trim().replace(/\s+/g, ' '));

    return {
      title,
      developer,
      coverImage: coverImage.slice(0, 100),
      description: description.slice(0, 150),
      videoUrl,
      sampleScores: scores.slice(0, 6),
      sampleReviews: reviewCards.slice(0, 5)
    };
  });

  console.log('Extracted game details:\n', JSON.stringify(data, null, 2));
  await browser.close();
}

inspectGameDetail().catch(console.error);

