import youtubeSr from 'youtube-sr';
const YouTube = (youtubeSr as any).default || youtubeSr;
import { YoutubeTranscript } from 'youtube-transcript';
import { geminiService } from './gemini.js';
import { YoutubeLetsplayInput } from '../db/gameRepository.js';

export class YouTubeService {
  async findAndAnalyzeLetsPlay(gameId: string, gameTitle: string): Promise<YoutubeLetsplayInput | null> {
    try {
      const query = `${gameTitle} gameplay walkthrough lets play`;
      console.log(`[YouTube] Searching for: "${query}"`);

      const searchResults = await YouTube.search(query, { limit: 3, type: 'video' });
      if (!searchResults || searchResults.length === 0) {
        console.warn(`[YouTube] No videos found for "${gameTitle}"`);
        return null;
      }

      // Pick top video
      const topVideo = searchResults[0];
      const videoId = topVideo.id || '';
      const videoTitle = topVideo.title || `${gameTitle} Gameplay`;
      const videoUrl = topVideo.url || `https://www.youtube.com/watch?v=${videoId}`;
      const channelName = topVideo.channel?.name || 'YouTube Streamer';
      const viewsCount = topVideo.views || 0;

      let transcriptText = '';
      try {
        const transcriptEntries = await YoutubeTranscript.fetchTranscript(videoId);
        transcriptText = transcriptEntries.map((t: any) => t.text).join(' ');
        console.log(`[YouTube] Extracted transcript (${transcriptText.length} chars) for video ${videoId}`);
      } catch (transcriptErr: any) {
        console.warn(`[YouTube] Could not fetch subtitles for ${videoId}:`, transcriptErr.message);
        // Fallback: use title and channel context
        transcriptText = `Видео летсплея игры ${gameTitle} от автора ${channelName} с названием "${videoTitle}". Количество просмотров: ${viewsCount}.`;
      }

      console.log(`[YouTube] Generating AI blogger conclusion for "${gameTitle}"...`);
      const bloggerConclusion = await geminiService.summarizeBloggerVideo(gameTitle, transcriptText);

      return {
        gameId,
        videoId,
        videoTitle,
        videoUrl,
        channelName,
        viewsCount,
        bloggerConclusion,
        transcriptSample: transcriptText.slice(0, 500)
      };
    } catch (err: any) {
      console.error(`[YouTube] Error analyzing video for "${gameTitle}":`, err.message);
      return null;
    }
  }
}

export const youtubeService = new YouTubeService();

import puppeteer from 'puppeteer-extra';
import StealthPlugin from 'puppeteer-extra-plugin-stealth';
import { Browser, Page } from 'puppeteer';
import { config } from '../config.js';
import { GameInput, GamePlatformInput } from '../db/gameRepository.js';

puppeteer.use(StealthPlugin());

export interface ScrapedGameData {
  gameInput: GameInput;
  criticReviews: string[];
  userReviews: string[];
}

export class MetacriticScraper {
  private browser: Browser | null = null;

  private async getBrowser(): Promise<Browser> {
    if (!this.browser || !this.browser.connected) {
      const launchOptions: any = {
        headless: config.headless,
        args: [
          '--no-sandbox',
          '--disable-setuid-sandbox',
          '--disable-dev-shm-usage',
          '--disable-gpu',
          '--no-first-run',
          '--no-zygote',
          '--single-process'
        ]
      };

      if (config.executablePath) {
        launchOptions.executablePath = config.executablePath;
      }

      this.browser = await puppeteer.launch(launchOptions);
    }
    return this.browser;
  }

  private async createPage(): Promise<Page> {
    const browser = await this.getBrowser();
    const page = await browser.newPage();
    await page.setUserAgent(
      'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36'
    );
    await page.setViewport({ width: 1280, height: 800 });

    // Block images, fonts and media to save bandwidth and speed up page load
    await page.setRequestInterception(true);
    page.on('request', (req) => {
      const type = req.resourceType();
      if (['font', 'media'].includes(type)) {
        req.abort();
      } else {
        req.continue();
      }
    });

    return page;
  }

  /**
   * 1. Get initial 20 game URLs from https://www.metacritic.com/game/
   */
  async getNewReleasesUrls(): Promise<string[]> {
    const page = await this.createPage();
    try {
      console.log('[Metacritic] Fetching New Releases from https://www.metacritic.com/game/ ...');
      await page.goto('https://www.metacritic.com/game/', {
        waitUntil: 'domcontentloaded',
        timeout: 25000
      });

      const urls = await page.evaluate(() => {
        const anchors = Array.from(document.querySelectorAll('a'));
        const found = new Set<string>();

        for (const a of anchors) {
          const href = a.getAttribute('href') || '';
          // We want /game/<slug>/ excluding top level sections like /game/all/, /game/ps5/, etc.
          const match = href.match(/^\/game\/([a-z0-9-]+)\/?$/i);
          if (match) {
            const slug = match[1].toLowerCase();
            const blacklist = ['all', 'pc', 'ps5', 'ps4', 'xbox-series-x', 'xbox-one', 'nintendo-switch', 'news', 'features'];
            if (!blacklist.includes(slug)) {
              found.add(`https://www.metacritic.com/game/${slug}/`);
            }
          }
        }
        return Array.from(found);
      });

      console.log(`[Metacritic] Discovered ${urls.length} games on /game/ page`);
      return urls;
    } finally {
      await page.close();
    }
  }

  /**
   * 2. Get game URLs from SEE ALL page: https://www.metacritic.com/browse/game/all/all-time/new/?page=N
   */
  async getSeeAllPageUrls(pageNumber: number): Promise<string[]> {
    const page = await this.createPage();
    try {
      const url = `https://www.metacritic.com/browse/game/all/all-time/new/?page=${pageNumber}`;
      console.log(`[Metacritic] Fetching SEE ALL page ${pageNumber} from ${url} ...`);
      await page.goto(url, {
        waitUntil: 'domcontentloaded',
        timeout: 25000
      });

      const urls = await page.evaluate(() => {
        const anchors = Array.from(document.querySelectorAll('a'));
        const found = new Set<string>();

        for (const a of anchors) {
          const href = a.getAttribute('href') || '';
          const match = href.match(/^\/game\/([a-z0-9-]+)\/?$/i);
          if (match) {
            const slug = match[1].toLowerCase();
            const blacklist = ['all', 'pc', 'ps5', 'ps4', 'xbox-series-x', 'xbox-one', 'nintendo-switch', 'news', 'features'];
            if (!blacklist.includes(slug)) {
              found.add(`https://www.metacritic.com/game/${slug}/`);
            }
          }
        }
        return Array.from(found);
      });

      console.log(`[Metacritic] Discovered ${urls.length} games on SEE ALL page ${pageNumber}`);
      return urls;
    } finally {
      await page.close();
    }
  }

  /**
   * Scrape full details for a game
   */
  async scrapeGameDetails(gameUrl: string, todayDate: string): Promise<ScrapedGameData | null> {
    const page = await this.createPage();
    try {
      console.log(`[Metacritic] Scraping details for ${gameUrl} ...`);
      await page.goto(gameUrl, { waitUntil: 'domcontentloaded', timeout: 25000 });

      // Extract JSON-LD and page DOM info
      const pageInfo = await page.evaluate(() => {
        let ld: any = null;
        try {
          const script = document.querySelector('script[type="application/ld+json"]');
          if (script && script.textContent) {
            ld = JSON.parse(script.textContent);
          }
        } catch {}

        const title = ld?.name || document.querySelector('h1')?.textContent?.trim() || '';
        const description = ld?.description || document.querySelector('.c-productDetails_description, [class*="description"]')?.textContent?.trim() || '';
        const coverImage = ld?.image || (document.querySelector('img[src*="catalog"], img[src*="hub"], .c-productHero_image img') as HTMLImageElement)?.src || '';

        // Video URL (trailer)
        let videoUrl = ld?.trailer?.embedUrl || ld?.trailer?.contentUrl || '';
        if (!videoUrl) {
          const videoEl = document.querySelector('video, iframe[src*="youtube"], iframe[src*="video"], a[href*="video"]');
          if (videoEl?.tagName === 'IFRAME') videoUrl = (videoEl as HTMLIFrameElement).src;
          else if (videoEl?.tagName === 'VIDEO') videoUrl = (videoEl as HTMLVideoElement).src;
        }

        // Developer
        const devSpans = Array.from(document.querySelectorAll('span, div, a'));
        const devLabel = devSpans.find(s => s.textContent?.trim() === 'Developer:');
        const developer = devLabel?.parentElement?.querySelector('a, span:last-child')?.textContent?.trim() ||
                          (ld?.author ? (Array.isArray(ld.author) ? ld.author[0]?.name : ld.author?.name) : '') ||
                          (ld?.publisher ? (Array.isArray(ld.publisher) ? ld.publisher[0]?.name : ld.publisher?.name) : '') ||
                          'Unknown Developer';

        // Platforms & Scores
        const metascoreFromLd = ld?.aggregateRating?.ratingValue ? parseInt(ld.aggregateRating.ratingValue, 10) : null;
        const platformsList: string[] = Array.isArray(ld?.gamePlatform) ? ld.gamePlatform : (ld?.gamePlatform ? [ld.gamePlatform] : ['PC']);

        // Look for userscore in DOM
        let userscore: number | null = null;
        const scoreEls = Array.from(document.querySelectorAll('[class*="userScore"], [class*="userscore"], [data-testid="userscore"]'));
        for (const el of scoreEls) {
          const text = el.textContent?.trim() || '';
          const match = text.match(/\b([0-9](\.[0-9])?)\b/);
          if (match && !isNaN(parseFloat(match[1]))) {
            userscore = parseFloat(match[1]);
            break;
          }
        }

        return {
          title,
          description,
          coverImage,
          videoUrl,
          developer,
          metascoreFromLd,
          platformsList,
          userscore
        };
      });

      if (!pageInfo.title) {
        console.warn(`[Metacritic] Could not find title on ${gameUrl}`);
        return null;
      }

      // Extract slug from URL
      const slugMatch = gameUrl.match(/\/game\/([a-z0-9-]+)/i);
      const slug = slugMatch ? slugMatch[1].toLowerCase() : pageInfo.title.toLowerCase().replace(/[^a-z0-9]+/g, '-');
      const gameId = slug;

      // Map platforms
      const platforms: GamePlatformInput[] = pageInfo.platformsList.map(p => ({
        platform: p,
        metascore: pageInfo.metascoreFromLd,
        userscore: pageInfo.userscore
      }));

      // Scrape critic reviews
      const criticReviews = await this.scrapeReviewsSubpage(gameUrl, 'critic-reviews');
      // Scrape user reviews
      const userReviews = await this.scrapeReviewsSubpage(gameUrl, 'user-reviews');

      return {
        gameInput: {
          id: gameId,
          title: pageInfo.title,
          slug,
          coverImage: pageInfo.coverImage,
          developer: pageInfo.developer,
          description: pageInfo.description,
          videoUrl: pageInfo.videoUrl,
          platforms,
          todayDate
        },
        criticReviews,
        userReviews
      };
    } catch (err: any) {
      console.error(`[Metacritic] Error scraping ${gameUrl}:`, err.message);
      return null;
    } finally {
      await page.close();
    }
  }

  /**
   * Helper to scrape quotes from critic-reviews or user-reviews subpages
   */
  private async scrapeReviewsSubpage(baseUrl: string, subpath: 'critic-reviews' | 'user-reviews'): Promise<string[]> {
    const page = await this.createPage();
    try {
      const url = `${baseUrl.replace(/\/$/, '')}/${subpath}/`;
      await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 15000 }).catch(() => {});

      const quotes = await page.evaluate(() => {
        // Collect quotes from review cards
        const reviewCards = Array.from(document.querySelectorAll('.c-siteReview, [class*="ReviewCard"], div.bg-gray-50, div[class*="min-h"]'));
        const texts: string[] = [];

        for (const card of reviewCards) {
          const txt = card.textContent?.trim().replace(/\s+/g, ' ') || '';
          // Filter out short or navigation texts
          if (txt.length > 60 && !txt.includes('Explore') && !txt.includes('Privacy Policy')) {
            texts.push(txt.slice(0, 400));
          }
        }

        return texts.slice(0, 10);
      });

      return quotes;
    } catch {
      return [];
    } finally {
      await page.close();
    }
  }

  async close() {
    if (this.browser) {
      await this.browser.close();
      this.browser = null;
    }
  }
}

export const metacriticScraper = new MetacriticScraper();

import { EventEmitter } from 'events';
import { metacriticScraper } from './metacritic.js';
import { geminiService } from './gemini.js';
import { youtubeService } from './youtube.js';
import { gameRepository } from '../db/gameRepository.js';
import { db } from '../db/database.js';

export interface WorkerProgressEvent {
  status: 'idle' | 'running' | 'completed' | 'error';
  currentGame: string;
  currentStep: string;
  processedCount: number;
  totalTarget: number;
  todayDate: string;
  seeAllPage: number;
}

export class CrawlWorker extends EventEmitter {
  private isRunning = false;

  get running() {
    return this.isRunning;
  }

  /**
   * Main entrypoint for processing 20 games
   */
  async runJob(isManual = false): Promise<boolean> {
    if (this.isRunning) {
      this.log('warn', 'Worker run requested, but a job is already in progress.');
      return false;
    }

    this.isRunning = true;
    const today = new Date().toISOString().split('T')[0];
    let state = gameRepository.getCrawlState();

    // Check if new day started
    if (state.last_run_date !== today) {
      this.log('info', `New day detected (${today} vs ${state.last_run_date}). Resetting daily crawl state.`);
      gameRepository.updateCrawlState({
        last_run_date: today,
        see_all_page: 1,
        total_processed_today: 0,
        status: 'running',
        current_step: 'New day initialized'
      });
      state = gameRepository.getCrawlState();
    } else {
      gameRepository.updateCrawlState({
        status: 'running',
        current_step: isManual ? 'Manual run started' : 'Hourly run started'
      });
    }

    this.emitProgress('running', '', 'Starting batch processing', 0, 20);

    try {
      // Determine which source to use
      let gameUrls: string[] = [];
      const isFirstBatchToday = state.total_processed_today === 0;

      if (isFirstBatchToday) {
        this.log('info', 'Batch 1 of the day: Scraping Games / New Releases section...');
        this.emitProgress('running', '', 'Scraping New Releases', 0, 20);
        gameUrls = await metacriticScraper.getNewReleasesUrls();
      }

      // If New Releases had fewer than 20 or if this is subsequent batch today, fetch from SEE ALL
      if (gameUrls.length < 20) {
        const pageToFetch = isFirstBatchToday ? 1 : state.see_all_page;
        this.log('info', `Fetching additional games from SEE ALL (page ${pageToFetch})...`);
        this.emitProgress('running', '', `Scraping SEE ALL page ${pageToFetch}`, 0, 20);
        const seeAllUrls = await metacriticScraper.getSeeAllPageUrls(pageToFetch);
        gameUrls = [...new Set([...gameUrls, ...seeAllUrls])];

        // Advance see_all_page for subsequent runs
        gameRepository.updateCrawlState({ see_all_page: pageToFetch + 1 });
      }

      this.log('info', `Discovered ${gameUrls.length} total potential game links. Filtering unprocessed today...`);

      // Filter out games already processed today
      const alreadyProcessedToday = new Set(
        (db.prepare('SELECT id FROM games WHERE last_processed_date = ?').all(today) as { id: string }[]).map(r => r.id)
      );

      const targetUrls: string[] = [];
      for (const url of gameUrls) {
        const slugMatch = url.match(/\/game\/([a-z0-9-]+)/i);
        const slug = slugMatch ? slugMatch[1].toLowerCase() : '';
        if (slug && !alreadyProcessedToday.has(slug)) {
          targetUrls.push(url);
          if (targetUrls.length >= 20) break;
        }
      }

      this.log('info', `Selected ${targetUrls.length} new games to process today (target: 20).`);

      if (targetUrls.length === 0) {
        this.log('info', 'No new unprocessed games found in current pages. Next hourly run will check further pages.');
        gameRepository.updateCrawlState({
          status: 'idle',
          current_step: 'No new games today',
          current_game: ''
        });
        this.emitProgress('idle', '', 'Finished (no new games)', 0, 20);
        this.isRunning = false;
        return true;
      }

      // Process each game
      let processedInThisRun = 0;

      for (let i = 0; i < targetUrls.length; i++) {
        const url = targetUrls[i];
        const stepIndex = i + 1;
        this.log('info', `[${stepIndex}/${targetUrls.length}] Scraping: ${url}`);
        this.emitProgress('running', url, `Scraping details (${stepIndex}/${targetUrls.length})`, stepIndex, targetUrls.length);

        try {
          // 1. Scrape Metacritic details
          const scraped = await metacriticScraper.scrapeGameDetails(url, today);
          if (!scraped) {
            this.log('warn', `Could not parse data for ${url}, skipping.`);
            continue;
          }

          const { gameInput, criticReviews, userReviews } = scraped;
          this.emitProgress('running', gameInput.title, `AI Review Analysis (${stepIndex}/${targetUrls.length})`, stepIndex, targetUrls.length);

          // 2. Compute Embedding for Similar Games
          const embeddingText = `${gameInput.title}. Developer: ${gameInput.developer}. Platforms: ${gameInput.platforms.map(p => p.platform).join(', ')}. ${gameInput.description || ''}`;
          try {
            const emb = await geminiService.getEmbedding(embeddingText);
            if (emb) gameInput.embedding = emb;
          } catch (embErr: any) {
            this.log('warn', `Embedding generation skipped for ${gameInput.title}: ${embErr.message}`);
          }

          // 3. Save / Update game in SQLite
          gameRepository.upsertGame(gameInput);
          this.log('success', `Saved game "${gameInput.title}" to database.`);

          // 4. AI Summarize Critic and User Reviews
          try {
            const reviewsSummary = await geminiService.summarizeReviews(gameInput.title, criticReviews, userReviews);
            gameRepository.upsertReviewsSummary({
              gameId: gameInput.id,
              criticsSummaryPros: reviewsSummary.criticsSummaryPros,
              criticsSummaryCons: reviewsSummary.criticsSummaryCons,
              usersSummaryPros: reviewsSummary.usersSummaryPros,
              usersSummaryCons: reviewsSummary.usersSummaryCons
            });
            this.log('success', `Generated AI reviews summary for "${gameInput.title}".`);
          } catch (sumErr: any) {
            this.log('warn', `Failed to summarize reviews for "${gameInput.title}": ${sumErr.message}`);
          }

          // 5. Additional Part 1: YouTube Let's Play & Blogger Conclusion
          this.emitProgress('running', gameInput.title, `YouTube Let's Play Analysis (${stepIndex}/${targetUrls.length})`, stepIndex, targetUrls.length);
          try {
            const youtubeResult = await youtubeService.findAndAnalyzeLetsPlay(gameInput.id, gameInput.title);
            if (youtubeResult) {
              gameRepository.upsertYoutubeLetsplay(youtubeResult);
              this.log('success', `Found & analyzed YouTube Let's Play for "${gameInput.title}" (${youtubeResult.videoTitle}).`);
            }
          } catch (ytErr: any) {
            this.log('warn', `YouTube processing error for "${gameInput.title}": ${ytErr.message}`);
          }

          processedInThisRun++;
          const newTotalToday = (gameRepository.getCrawlState().total_processed_today || 0) + 1;
          gameRepository.updateCrawlState({
            total_processed_today: newTotalToday,
            current_game: gameInput.title
          });

          // Polite delay between games
          await new Promise(res => setTimeout(res, 1500));
        } catch (itemErr: any) {
          this.log('error', `Error processing game at ${url}: ${itemErr.message}`);
        }
      }

      this.log('success', `Batch complete! Successfully processed ${processedInThisRun} games.`);
      gameRepository.updateCrawlState({
        status: 'idle',
        current_step: `Completed batch of ${processedInThisRun} games`,
        current_game: ''
      });
      this.emitProgress('idle', '', `Completed (${processedInThisRun} games processed)`, processedInThisRun, targetUrls.length);
      return true;
    } catch (err: any) {
      this.log('error', `Critical worker error: ${err.message}`);
      gameRepository.updateCrawlState({
        status: 'error',
        current_step: `Error: ${err.message}`
      });
      this.emitProgress('error', '', `Error: ${err.message}`, 0, 20);
      return false;
    } finally {
      this.isRunning = false;
      await metacriticScraper.close();
    }
  }

  private log(level: 'info' | 'warn' | 'error' | 'success', message: string, gameId?: string) {
    console.log(`[Worker][${level.toUpperCase()}] ${message}`);
    gameRepository.addWorkerLog(level, message, gameId);
    this.emit('log', { level, message, gameId, timestamp: new Date().toISOString() });
  }

  private emitProgress(
    status: 'idle' | 'running' | 'completed' | 'error',
    currentGame: string,
    currentStep: string,
    processedCount: number,
    totalTarget: number
  ) {
    const state = gameRepository.getCrawlState();
    const event: WorkerProgressEvent = {
      status,
      currentGame,
      currentStep,
      processedCount,
      totalTarget,
      todayDate: state.last_run_date,
      seeAllPage: state.see_all_page
    };
    this.emit('progress', event);
  }
}

export const crawlWorker = new CrawlWorker();

import cron from 'node-cron';
import { crawlWorker } from './worker.js';
import { gameRepository } from '../db/gameRepository.js';

export function startScheduler() {
  console.log('[Scheduler] Initializing cron job: running every hour (0 * * * *)');

  // Run once every hour at minute 0
  cron.schedule('0 * * * *', async () => {
    console.log('[Scheduler] Triggering scheduled hourly game crawling job...');
    await crawlWorker.runJob(false);
  });

  // Check if database has 0 games on startup, and trigger initial run automatically if idle
  const allGames = gameRepository.getAllGames();
  if (allGames.length === 0) {
    console.log('[Scheduler] Database is empty on startup. Triggering initial 20 games crawl...');
    setTimeout(() => {
      crawlWorker.runJob(false).catch(err => {
        console.error('[Scheduler] Initial crawl failed:', err);
      });
    }, 2000);
  }
}

import { WebSocketServer, WebSocket } from 'ws';
import { Server } from 'http';
import { crawlWorker, WorkerProgressEvent } from '../services/worker.js';
import { gameRepository } from '../db/gameRepository.js';

export function setupWebSocket(server: Server) {
  const wss = new WebSocketServer({ server, path: '/ws' });

  function broadcast(type: string, data: any) {
    const payload = JSON.stringify({ type, data, timestamp: new Date().toISOString() });
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(payload);
      }
    }
  }

  wss.on('connection', (ws: WebSocket) => {
    // Send initial status and recent logs
    const state = gameRepository.getCrawlState();
    const recentLogs = gameRepository.getRecentLogs(50);

    ws.send(JSON.stringify({
      type: 'init',
      data: {
        state,
        isRunning: crawlWorker.running,
        logs: recentLogs.reverse()
      }
    }));
  });

  // Forward worker events
  crawlWorker.on('progress', (event: WorkerProgressEvent) => {
    broadcast('progress', event);
  });

  crawlWorker.on('log', (logEntry) => {
    broadcast('log', logEntry);
  });

  console.log('[WebSocket] Real-time WebSocket server initialized on /ws');
  return wss;
}

import express from 'express';
import cors from 'cors';
import path from 'path';
import fs from 'fs';
import { gameRepository } from '../db/gameRepository.js';
import { crawlWorker } from '../services/worker.js';

export function createApp() {
  const app = express();

  app.use(cors());
  app.use(express.json());

  // API Routes
  // 1. Get all games with search, platform filter, and sorting
  app.get('/api/games', (req, res) => {
    try {
      const { search, platform, sortBy, sortOrder } = req.query;
      const games = gameRepository.getAllGames({
        search: search ? String(search) : undefined,
        platform: platform ? String(platform) : undefined,
        sortBy: sortBy as any,
        sortOrder: sortOrder as any
      });
      res.json({ success: true, data: games });
    } catch (err: any) {
      res.status(500).json({ success: false, error: err.message });
    }
  });

  // 2. Get distinct platforms for filter dropdown
  app.get('/api/platforms', (req, res) => {
    try {
      const platforms = gameRepository.getAllPlatforms();
      res.json({ success: true, data: platforms });
    } catch (err: any) {
      res.status(500).json({ success: false, error: err.message });
    }
  });

  // 3. Get single game by ID (with platforms, AI reviews, YouTube, and similar games)
  app.get('/api/games/:id', (req, res) => {
    try {
      const game = gameRepository.getGameById(req.params.id);
      if (!game) {
        return res.status(404).json({ success: false, error: 'Game not found' });
      }
      res.json({ success: true, data: game });
    } catch (err: any) {
      res.status(500).json({ success: false, error: err.message });
    }
  });

  // 4. Get worker status & recent logs (monitoring)
  app.get('/api/worker/status', (req, res) => {
    try {
      const state = gameRepository.getCrawlState();
      const logs = gameRepository.getRecentLogs(50);
      res.json({
        success: true,
        data: {
          state,
          isRunning: crawlWorker.running,
          logs
        }
      });
    } catch (err: any) {
      res.status(500).json({ success: false, error: err.message });
    }
  });

  // 5. Force run button trigger
  app.post('/api/worker/run', async (req, res) => {
    if (crawlWorker.running) {
      return res.status(409).json({
        success: false,
        message: 'Процесс обработки уже выполняется!'
      });
    }

    // Launch worker asynchronously
    crawlWorker.runJob(true).catch(err => {
      console.error('[API] Worker run error:', err);
    });

    res.json({
      success: true,
      message: 'Процесс сбора данных запущен в фоне.'
    });
  });

  // Serve Frontend build in production if available
  const frontendDist = path.resolve(process.cwd(), 'frontend', 'dist');
  if (fs.existsSync(frontendDist)) {
    app.use(express.static(frontendDist));
    app.get('*', (req, res) => {
      if (!req.path.startsWith('/api') && !req.path.startsWith('/ws')) {
        res.sendFile(path.join(frontendDist, 'index.html'));
      }
    });
  }

  return app;
}

import http from 'http';
import { config } from './config.js';
import { initDatabase } from './db/database.js';
import { createApp } from './server/app.js';
import { setupWebSocket } from './server/ws.js';
import { startScheduler } from './services/scheduler.js';

async function bootstrap() {
  console.log('--- Metacritic AI Game Analyzer Server ---');
  console.log(`Node environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Port: ${config.port}`);

  // 1. Initialize SQLite schema
  initDatabase();
  console.log('[DB] SQLite database initialized successfully.');

  // 2. Setup Express & HTTP Server
  const app = createApp();
  const server = http.createServer(app);

  // 3. Setup WebSocket for real-time monitoring
  setupWebSocket(server);

  // 4. Start cron hourly scheduler
  startScheduler();

  // 5. Start listening
  server.listen(config.port, () => {
    console.log(`[Server] Server listening on http://localhost:${config.port}`);
    console.log(`[Server] REST API available at http://localhost:${config.port}/api/games`);
    console.log(`[Server] WebSocket available at ws://localhost:${config.port}/ws`);
  });
}

bootstrap().catch(err => {
  console.error('[Bootstrap] Fatal startup error:', err);
  process.exit(1);
});

