  onForceRun: () => void;
}

export const WorkerDashboard: React.FC<WorkerDashboardProps> = ({
  isOpen,
  onClose,
  crawlState,
  progress,
  logs,
  isRunning,
  totalGames,
  onForceRun
}) => {
  const terminalRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom of logs
  useEffect(() => {
    if (terminalRef.current) {
      terminalRef.current.scrollTop = terminalRef.current.scrollHeight;
    }
  }, [logs]);

  if (!isOpen) return null;

  const currentStep = progress?.currentStep || crawlState?.current_step || 'Ожидание запуска';
  const currentGame = progress?.currentGame || crawlState?.current_game || '';
  const processedCount = progress?.processedCount || (isRunning ? 1 : 0);
  const totalTarget = progress?.totalTarget || 20;
  const percent = Math.min(100, Math.round((processedCount / totalTarget) * 100));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-6 bg-black/80 backdrop-blur-md overflow-y-auto animate-fadeIn">
      <div className="relative w-full max-w-4xl bg-slate-900 border border-slate-800 rounded-3xl shadow-2xl overflow-hidden my-auto max-h-[90vh] flex flex-col">
        {/* Header */}
        <div className="px-6 py-4 border-b border-slate-800 flex items-center justify-between bg-slate-950/60">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-lg bg-sky-500/10 border border-sky-500/20 flex items-center justify-center text-sky-400">
              <Activity className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-base font-bold text-white">Мониторинг Воркера</h2>
                <span className="text-[10px] uppercase font-bold tracking-wider px-2 py-0.5 rounded-full bg-sky-500/10 text-sky-400 border border-sky-500/20">
                  Доп. часть 2
                </span>
              </div>
              <p className="text-xs text-slate-400">Реальное время (WebSocket поток)</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={onClose}
              className="p-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white transition-colors cursor-pointer"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        <div className="p-6 overflow-y-auto space-y-6 flex-1">
          {/* Status & Stats Cards */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            {/* Status */}
            <div className="bg-slate-950/70 border border-slate-800/80 rounded-2xl p-3 flex flex-col justify-between">
              <span className="text-[11px] font-medium text-slate-400">Статус воркера</span>
              <div className="flex items-center gap-2 mt-2">
                <span className="relative flex h-3 w-3">
                  {isRunning && (
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-sky-400 opacity-75"></span>
                  )}
                  <span
                    className={`relative inline-flex rounded-full h-3 w-3 ${
                      isRunning
                        ? 'bg-sky-500'
                        : crawlState?.status === 'error'
                        ? 'bg-rose-500'
                        : 'bg-emerald-500'
                    }`}
                  ></span>
                </span>
                <span className="font-bold text-sm text-white">
                  {isRunning ? 'Работает' : crawlState?.status === 'error' ? 'Ошибка' : 'В ожидании'}
                </span>
              </div>
            </div>

            {/* Today Date */}
            <div className="bg-slate-950/70 border border-slate-800/80 rounded-2xl p-3 flex flex-col justify-between">
              <span className="text-[11px] font-medium text-slate-400 flex items-center gap-1">
                <Calendar className="w-3 h-3 text-amber-400" />
                <span>Текущая дата</span>
              </span>
              <span className="font-mono font-bold text-sm text-slate-200 mt-2">
                {crawlState?.last_run_date || new Date().toISOString().split('T')[0]}
              </span>
            </div>

            {/* Total Today */}
            <div className="bg-slate-950/70 border border-slate-800/80 rounded-2xl p-3 flex flex-col justify-between">
              <span className="text-[11px] font-medium text-slate-400 flex items-center gap-1">
                <Layers className="w-3 h-3 text-purple-400" />
                <span>Собрано сегодня</span>
              </span>
              <span className="font-mono font-bold text-sm text-amber-400 mt-2">
                {crawlState?.total_processed_today || 0} игр
              </span>
            </div>

            {/* Total in DB */}
            <div className="bg-slate-950/70 border border-slate-800/80 rounded-2xl p-3 flex flex-col justify-between">
              <span className="text-[11px] font-medium text-slate-400 flex items-center gap-1">
                <Database className="w-3 h-3 text-emerald-400" />
                <span>Всего в базе SQLite</span>
              </span>
              <span className="font-mono font-bold text-sm text-emerald-400 mt-2">
                {totalGames} игр
              </span>
            </div>
          </div>

          {/* Current Job Progress */}
          <div className="bg-slate-950/80 border border-slate-800 rounded-2xl p-4">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2">
                <span className="text-xs font-bold text-slate-300">Текущий процесс:</span>
                <span className="text-xs text-amber-400 font-medium">
                  {currentStep}
                </span>
                {currentGame && (
                  <span className="text-xs text-slate-400 font-mono truncate max-w-xs">
                    ({currentGame})
                  </span>
                )}
              </div>
              <span className="text-xs font-mono font-bold text-slate-400">
                {isRunning ? `${processedCount} / ${totalTarget}` : 'Готов к работе'}
              </span>
            </div>

            {/* Progress bar */}
            <div className="w-full h-2.5 bg-slate-900 rounded-full overflow-hidden border border-slate-800 relative">
              <div
                className={`h-full transition-all duration-500 rounded-full ${
                  isRunning
                    ? 'bg-gradient-to-r from-sky-500 via-amber-500 to-orange-500 animate-pulse'
                    : 'bg-emerald-500'
                }`}
                style={{ width: `${isRunning ? percent : 100}%` }}
              />
            </div>

            {/* Force Run Button */}
            <div className="mt-4 flex items-center justify-between pt-3 border-t border-slate-800/80">
              <div className="text-xs text-slate-400">
                Авто-запуск настроен: <strong>1 раз в час</strong> (0 * * * *). Ротация по дням активна.
              </div>
              <button
                onClick={onForceRun}
                disabled={isRunning}
                className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all shadow-lg cursor-pointer ${
                  isRunning
                    ? 'bg-slate-800 text-slate-500 cursor-not-allowed border border-slate-700'
                    : 'bg-gradient-to-r from-amber-500 to-orange-600 hover:from-amber-400 hover:to-orange-500 text-slate-950 active:scale-95 shadow-orange-500/20'
                }`}
              >
                {isRunning ? (
                  <>
                    <Activity className="w-4 h-4 animate-spin" />
                    <span>Идет обработка...</span>
                  </>
                ) : (
                  <>
                    <Play className="w-4 h-4 fill-current" />
                    <span>Запустить сбор 20 игр прямо сейчас</span>
                  </>
                )}
              </button>
            </div>
          </div>

          {/* Live Log Terminal */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2 text-xs font-bold text-slate-300">
                <Terminal className="w-4 h-4 text-emerald-400" />
                <span>Живой лог событий воркера (Live Stream)</span>
              </div>
              <span className="text-[11px] text-slate-500 font-mono">
                {logs.length} сообщений
              </span>
            </div>

            <div
              ref={terminalRef}
              className="bg-black/90 border border-slate-800 rounded-2xl p-4 font-mono text-xs h-64 overflow-y-auto space-y-1.5 shadow-inner"
            >
              {logs.length === 0 ? (
                <div className="text-slate-500 text-center py-8">
                  Логи пока отсутствуют. Нажмите кнопку запуска сбора выше.
                </div>
              ) : (
                logs.map((log, idx) => {
                  const time = log.timestamp ? log.timestamp.split('T')[1]?.slice(0, 8) : '';
                  let levelColor = 'text-sky-400';
                  let icon = 'ℹ';
                  if (log.level === 'success') {
                    levelColor = 'text-emerald-400';
                    icon = '✓';
                  } else if (log.level === 'warn') {
                    levelColor = 'text-amber-400';
                    icon = '⚠';
                  } else if (log.level === 'error') {
                    levelColor = 'text-rose-400';
                    icon = '✕';
                  }

                  return (
                    <div key={idx} className="flex items-start gap-2 leading-relaxed">
                      <span className="text-slate-600 select-none">[{time}]</span>
                      <span className={`font-bold ${levelColor} select-none`}>
                        {icon} [{log.level.toUpperCase()}]:
                      </span>
                      <span className="text-slate-300 flex-1 break-all">{log.message}</span>
                    </div>
                  );
                })
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Navbar } from './components/Navbar';
import { FilterBar } from './components/FilterBar';
import { GameCard } from './components/GameCard';
import { GameModal } from './components/GameModal';
import { WorkerDashboard } from './components/WorkerDashboard';
import {
  GameItem,
  CrawlState,
  WorkerLog,
  WorkerProgressPayload
} from './types';
import { Gamepad2, Sparkles, RefreshCw, AlertTriangle, Layers } from 'lucide-react';

export function App() {
  const [games, setGames] = useState<GameItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Filters
  const [search, setSearch] = useState('');
  const [selectedPlatform, setSelectedPlatform] = useState('');
  const [availablePlatforms, setAvailablePlatforms] = useState<string[]>([]);
  const [sortBy, setSortBy] = useState<'recent' | 'metascore' | 'userscore' | 'title'>('recent');

  // Modal states
  const [selectedGameId, setSelectedGameId] = useState<string | null>(null);
  const [isMonitorOpen, setIsMonitorOpen] = useState(false);

  // Worker real-time states
  const [crawlState, setCrawlState] = useState<CrawlState | null>(null);
  const [progress, setProgress] = useState<WorkerProgressPayload | null>(null);
  const [logs, setLogs] = useState<WorkerLog[]>([]);
  const [isRunning, setIsRunning] = useState(false);

  // Load Games
  const fetchGames = useCallback(async () => {
    try {
      const params = new URLSearchParams();
      if (search.trim()) params.set('search', search.trim());
      if (selectedPlatform) params.set('platform', selectedPlatform);
      if (sortBy) params.set('sortBy', sortBy);

      const res = await fetch(`/api/games?${params.toString()}`);
      const json = await res.json();
      if (json.success) {
        setGames(json.data);
      } else {
        setError(json.error || 'Ошибка загрузки игр');
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [search, selectedPlatform, sortBy]);

  // Load Platforms
  const fetchPlatforms = async () => {
    try {
      const res = await fetch('/api/platforms');
      const json = await res.json();
      if (json.success) {
        setAvailablePlatforms(json.data);
      }
    } catch (e) {
      console.warn('Failed to fetch platforms:', e);
    }
  };

  useEffect(() => {
    fetchGames();
  }, [fetchGames]);

  useEffect(() => {
    fetchPlatforms();
  }, []);

  // Setup WebSocket Connection
  useEffect(() => {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = `${protocol}//${window.location.host}/ws`;
    let ws: WebSocket | null = null;
    let reconnectTimeout: any = null;

    function connect() {
      ws = new WebSocket(wsUrl);

      ws.onopen = () => {
        console.log('[WebSocket] Connected to worker stream');
      };

      ws.onmessage = (event) => {
        try {
          const msg = JSON.parse(event.data);
          if (msg.type === 'init') {
            setCrawlState(msg.data.state);
            setIsRunning(msg.data.isRunning);
            setLogs(msg.data.logs || []);
          } else if (msg.type === 'progress') {
            const p: WorkerProgressPayload = msg.data;
            setProgress(p);
            setIsRunning(p.status === 'running');
            if (p.status === 'idle' || p.status === 'completed') {
              // Refresh games list when worker finishes
              fetchGames();
              fetchPlatforms();
            }
          } else if (msg.type === 'log') {
            setLogs((prev) => [...prev, msg.data]);
            // If game was saved, refresh catalog
            if (msg.data.level === 'success') {
              fetchGames();
            }
          }
        } catch (err) {
          console.error('[WebSocket] Message parse error:', err);
        }
      };

      ws.onclose = () => {
        console.log('[WebSocket] Disconnected, attempting reconnect in 3s...');
        reconnectTimeout = setTimeout(connect, 3000);
      };

      ws.onerror = (e) => {
        console.warn('[WebSocket] Error:', e);
      };
    }

    connect();

    return () => {
      if (ws) ws.close();
      clearTimeout(reconnectTimeout);
    };
  }, [fetchGames]);

  // Force Run Handler
  const handleForceRun = async () => {
    try {
      setIsRunning(true);
      const res = await fetch('/api/worker/run', { method: 'POST' });
      const json = await res.json();
      if (!json.success) {
        alert(json.message || 'Ошибка запуска воркера');
        setIsRunning(false);
      } else {
        setIsMonitorOpen(true);
      }
    } catch (err: any) {
      alert(`Ошибка запроса: ${err.message}`);
      setIsRunning(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#0b0f19] text-slate-100 flex flex-col selection:bg-amber-500 selection:text-slate-950">
      {/* Navigation */}
      <Navbar
        crawlState={crawlState}
        isRunning={isRunning}
        totalGames={games.length}
        onOpenMonitor={() => setIsMonitorOpen(true)}
        onForceRun={handleForceRun}
      />

      {/* Main Content Area */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Banner / Intro */}
        <div className="relative rounded-3xl overflow-hidden bg-gradient-to-r from-slate-900 via-slate-900/90 to-slate-950 border border-slate-800/80 p-6 sm:p-8 mb-8 shadow-2xl">
          <div className="relative z-10 max-w-2xl">
            <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-amber-500/10 text-amber-400 border border-amber-500/20 text-xs font-semibold mb-3">
              <Sparkles className="w-3.5 h-3.5" />
              <span>Metacritic Game Releases & AI Intelligence</span>
            </div>
            <h1 className="text-2xl sm:text-4xl font-extrabold text-white tracking-tight leading-tight">
              Каталог игр Metacritic с авто-аналитикой отзывов
            </h1>
            <p className="text-sm sm:text-base text-slate-400 mt-2 leading-relaxed">
              Сервис каждый час автоматически собирает по 20 новых релизов, суммаризирует отзывы критиков и игроков через <strong>Gemini 2.5 Flash Lite</strong>, подбирает похожие игры и находит популярные летсплеи YouTube.
            </p>
          </div>
          <div className="absolute right-0 top-0 bottom-0 w-1/3 bg-gradient-to-l from-orange-500/10 via-amber-500/5 to-transparent pointer-events-none" />
        </div>

        {/* Filter & Search Bar */}
        <FilterBar
          search={search}
          onSearchChange={setSearch}
          selectedPlatform={selectedPlatform}
          onPlatformChange={setSelectedPlatform}
          availablePlatforms={availablePlatforms}
          sortBy={sortBy}
          onSortByChange={setSortBy}
          totalFiltered={games.length}
        />

        {/* Content States */}
        {loading ? (
          <div className="py-24 flex flex-col items-center justify-center gap-4">
            <div className="w-12 h-12 border-4 border-amber-500/20 border-t-amber-500 rounded-full animate-spin" />
            <p className="text-sm text-slate-400 font-medium">Загрузка каталога игр...</p>
          </div>
        ) : error ? (
          <div className="py-16 text-center bg-rose-950/20 border border-rose-900/30 rounded-3xl p-8">
            <AlertTriangle className="w-10 h-10 text-rose-400 mx-auto mb-3" />
            <p className="text-sm font-semibold text-rose-300">{error}</p>
            <button
              onClick={fetchGames}
              className="mt-4 inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-xs font-semibold text-white transition-all cursor-pointer"
            >
              <RefreshCw className="w-3.5 h-3.5" />
              <span>Повторить запрос</span>
            </button>
          </div>
        ) : games.length === 0 ? (
          <div className="py-20 text-center bg-slate-900/40 border border-slate-800/80 rounded-3xl p-8 max-w-lg mx-auto">
            <div className="w-14 h-14 rounded-2xl bg-slate-800/60 flex items-center justify-center mx-auto mb-4 text-slate-400">
              <Gamepad2 className="w-7 h-7" />
            </div>
            <h3 className="text-lg font-bold text-white mb-2">Игры не найдены</h3>
            <p className="text-sm text-slate-400 mb-6">
              {search || selectedPlatform
                ? 'Попробуйте сбросить параметры поиска или фильтра по платформам.'
                : 'База данных пока пуста. Нажмите кнопку сбора, чтобы загрузить первые 20 игр с Metacritic.'}
            </p>
            {search || selectedPlatform ? (
              <button
                onClick={() => {
                  setSearch('');
                  setSelectedPlatform('');
                }}
                className="px-4 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-xs font-semibold text-white transition-all cursor-pointer"
              >
                Сбросить фильтры
              </button>
            ) : (
              <button
                onClick={handleForceRun}
                disabled={isRunning}
                className="px-5 py-2.5 rounded-xl bg-gradient-to-r from-amber-500 to-orange-600 text-slate-950 font-bold text-xs shadow-lg shadow-orange-500/20 hover:from-amber-400 hover:to-orange-500 transition-all cursor-pointer"
              >
                Запустить сбор первых 20 игр
              </button>
            )}
          </div>
        ) : (
          /* Games Grid */
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6 animate-fadeIn">
            {games.map((game) => (
              <GameCard
                key={game.id}
                game={game}
                onClick={() => setSelectedGameId(game.id)}
              />
            ))}
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="border-t border-slate-800/80 bg-slate-950 py-6 text-center text-xs text-slate-500">
        <div className="max-w-7xl mx-auto px-4 flex flex-col sm:flex-row items-center justify-between gap-3">
          <p>© 2026 Metacritic AI Game Analyzer • Выполнено для Skytec Games</p>
          <p className="font-mono text-[11px] text-slate-600">
            Node.js 24 • React 19 • SQLite • Puppeteer • Gemini 2.5 Flash Lite
          </p>
        </div>
      </footer>

      {/* Game Detail Modal */}
      <GameModal
        gameId={selectedGameId}
        onClose={() => setSelectedGameId(null)}
        onSelectGame={(id) => setSelectedGameId(id)}
      />

      {/* Worker Monitoring Dashboard Modal */}
      <WorkerDashboard
        isOpen={isMonitorOpen}
        onClose={() => setIsMonitorOpen(false)}
        crawlState={crawlState}
        progress={progress}
        logs={logs}
        isRunning={isRunning}
        totalGames={games.length}
        onForceRun={handleForceRun}
      />
    </div>
  );
}

export default App;

